steps.codeExample:
// In your component
return (
  <div style={{ display: 'flex' }}>
    <div>Item 1</div>
    <div>Item 2</div>
    <div>Item 3</div>
  </div>
);

// Centering both ways
<div style={{ 
  display: 'flex', 
  justifyContent: 'center',
  alignItems: 'center',
  height: '200px'
}}>
  <div>Perfectly centered!</div>
</div>

// Adding space between items
<div style={{ 
  display: 'flex',
  gap: '20px'
}}>
  <div>Item 1</div>
  <div>Item 2</div>
</div>
